	return m.chain.LatestConfirmed(ctx, m.chain.GetCallOptsWithDesiredRpcHeadBlockNumber(&bind.CallOpts{Context: ctx}))
})
if err != nil {
	log.Error("Could not get latest confirmed assertion", "err", err)
	return
}
