	return m.chain.ReadAssertionCreationInfo(ctx, latestConfirmed.Id())
})
if err != nil {
	log.Error("Could not get latest confirmed assertion", "err", err)
	return
}

m.assertionChainData.Lock()
m.assertionChainData.latestAgreedAssertion = latestConfirmed.Id()
m.assertionChainData.canonicalAssertions[latestConfirmed.Id()] = latestConfirmedInfo
if !m.disablePosting {
	close(m.startPostingSignal)
}
m.assertionChainData.Unlock()

func (m *Manager) LatestAgreedState(ctx context.Context) (protocol.GoGlobalState, error) {
	latestAgreedAssertion := m.assertionManager.LatestAgreedAssertion()
	info, err := m.chain.ReadAssertionCreationInfo(ctx, latestAgreedAssertion)
	if err != nil {
		return protocol.GoGlobalState{}, err
	}
	return protocol.GoExecutionStateFromSolidity(info.AfterState).GlobalState, nil
}

